        <ul>
          {posts.map((post: any) => (
            <li key={post.id}>
              <Link href={`/blog/${post.id}`}>{post.title}</Link>
            </li>
          ))}
        </ul>

        <Link href="/blog">
          View All Posts
        </Link>
      </div>
    </>
  )
}

