}

import { Metadata } from 'next'
import Link from 'next/link'
import { notFound } from 'next/navigation'

export async function generateMetadata({ params }: { params: { id: string } }) {
  const post = await fetch(`https://jsonplaceholder.typicode.com/posts/${params.id}`)
    .then(res => res.json())
    .catch(() => null)

  if (!post) {
    return {
      title: 'Post Not Found',
    }
  }

  return {
    title: `${post.title} - My Blog`,
    description: post.body.substring(0, 160),
    openGraph: {
      title: post.title,
      description: post.body.substring(0, 160),
    },
  }
}

export async function generateStaticParams() {
  const posts = await fetch('https://jsonplaceholder.typicode.com/posts')
    .then(res => res.json())

  return posts.slice(0, 10).map((post: any) => ({
    id: post.id.toString(),
  }))
}

export default async function BlogPost({ params }: { params: { id: string } }) {
  try {
    const [post, comments] = await Promise.all([
      fetch(`https://jsonplaceholder.typicode.com/posts/${params.id}`).then(res => res.json()),
      fetch(`https://jsonplaceholder.typicode.com/posts/${params.id}/comments`).then(res => res.json()),
    ])

    return (
      <>
        <article>
          <Link href="/blog">← Back</Link>

          <h1>{post.title}</h1>
          <p>{post.body}</p>

          <h2>Comments ({comments.length})</h2>
          <div className="comments">
            {comments.map((comment: any) => (
              <div key={comment.id} className="comment">
                <h3>{comment.name}</h3>
                <p>{comment.body}</p>
                <small>By: {comment.email}</small>
              </div>
            ))}
          </div>
        </article>
      </>
    )
  } catch (error) {
    notFound()
  }
}

